        var owned=Path.Combine(directory,"fel-owned-"+index+".mp4");var baseFile=Path.Combine(directory,"fel-base-"+index+".mp4");var elFile=Path.Combine(directory,"fel-enhancement-"+index+".hevc");var encoded=Path.Combine(directory,"fel-rendered-"+index+".mp4");var raw=Path.Combine(directory,"fel-rendered-"+index+".hevc");var patched=Path.Combine(directory,"fel-patched-"+index+".hevc");var output=Path.Combine(directory,"fel-reconstructed-"+index+".mp4");
        await RunAsync(ffmpeg,["-y","-v","error","-protocol_whitelist","file,pipe","-enable_drefs","0","-use_absolute_path","0","-i",input,"-map","0:v:0","-c","copy","-strict","unofficial",owned],ct,rejectDiagnostics:true).ConfigureAwait(false);
        var samples=new List<Mp4MelBridge.Sample>();var models=new List<DolbyFelProgram>();var offsets=new List<long>();var cache=new Dictionary<string,DolbyFelProgram>();var metadataBytes=0;
        using(var enhancement=File.Create(elFile))
        {
            await InspectHdrPacketsAsync(ffmpeg,owned,(position,nals)=>
            {
                ct.ThrowIfCancellationRequested();if(samples.Count>0&&position<=samples[^1].Position)throw new NotSupportedException("FEL coded samples must have a unique file order.");var rp=nals.Where(n=>HevcMetadataTransport.Type(n)==62).ToArray();if(rp.Length!=1)throw new InvalidDataException("FEL requires exactly one independent RPU per coded picture.");var key=Convert.ToHexString(rp[0]);if(!cache.TryGetValue(key,out var model)){if(cache.Count>=4096||(metadataBytes+=rp[0].Length)>32*1024*1024)throw new InvalidDataException("FEL metadata inventory exceeds its bounds.");cache[key]=model=DolbyFelProgram.Read(rp[0],single);}Mp4MelBridge.SampleBytes(nals,_=>model.SingleLayerRpu,single);models.Add(model);samples.Add(new(position,nals.Sum(n=>n.Length+4)));offsets.Add(enhancement.Position);Write([0x46,1,0x50]);var pictures=0;
                foreach(var nal in nals.Where(n=>HevcMetadataTransport.Type(n)==63)){var inner=nal.AsSpan(2).ToArray();var type=HevcMetadataTransport.Type(inner);if(type is 62 or 63||(inner[0]&1)!=0||(inner[1]>>3)!=0)throw new NotSupportedException("Unsupported nested FEL layer header.");if(type==35)continue;if(type<=31)pictures++;Write(inner);}if(!single&&pictures==0)throw new InvalidDataException("FEL access unit has no enhancement picture.");
