        var elFrames=single?sequence.Select(i=>new EnhancementFrame(offsets[i],source.Width,source.Height)).ToList():await ReadEnhancementFramesAsync(ffmpeg,elFile,ct).ConfigureAwait(false);if(elFrames.Count!=frames.Count)throw new InvalidDataException("FEL enhancement/base picture counts differ.");var ew=elFrames[0].Width;var eh=elFrames[0].Height;for(var i=0;i<sequence.Length;i++){var at=offsets.BinarySearch(elFrames[i].Position);if(at<0)at=~at-1;if(at!=sequence[i]||elFrames[i].Width!=ew||elFrames[i].Height!=eh)throw new InvalidDataException("FEL enhancement pictures do not match base presentation order.");}
        var rate=baseStream.FrameRate.Split('/');if(rate.Length!=2||!decimal.TryParse(rate[0],out var rn)||!decimal.TryParse(rate[1],out var rd)||rn<=0||rd<=0||rn/rd>120)throw new NotSupportedException("FEL requires a declared rational source cadence.");var duration=rd/rn;if(frames.Any(f=>Math.Abs(f.Duration-duration)>0.000002m)||frames.Select((f,i)=>Math.Abs(f.Time-frames[0].Time-i*duration)).Any(gap=>gap>0.000002m))throw new NotSupportedException("FEL reconstruction currently requires a stable declared source frame clock.");if(frames[0].Metadata.Static.MasterDisplay is null)throw new NotSupportedException("FEL reconstruction requires source mastering metadata.");var pixels=checked(source.Width*source.Height);var elPixels=checked(ew*eh);if((long)(pixels*2+elPixels)*6>256*1024*1024)throw new NotSupportedException("FEL raster memory exceeds its bound.");var b=new byte[pixels*6];var e=new byte[elPixels*6];var reconstructed=new byte[pixels*6];
