    }
    private sealed record EnhancementFrame(long Position,int Width,int Height);
    private static async Task<List<EnhancementFrame>> ReadEnhancementFramesAsync(string ffmpeg,string path,CancellationToken ct)
    {
        await using var process=new RawVideoPipe(RequireProbe(ffmpeg,"inspect FEL pictures"),["-v","error","-threads","1","-max_alloc","134217728","-protocol_whitelist","file,pipe","-f","hevc","-select_streams","v:0","-show_frames","-show_entries","frame=pkt_pos,width,height,pix_fmt,interlaced_frame","-of","xml",path],false,ct);using var xml=XmlReader.Create(process.Stream,new XmlReaderSettings{Async=true,DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=64*1024*1024});var doc=await XDocument.LoadAsync(xml,LoadOptions.None,ct).ConfigureAwait(false);var frames=doc.Descendants("frame").Select(f=>
        {
            if((string?)f.Attribute("pix_fmt")!="yuv420p10le"||(string?)f.Attribute("interlaced_frame")!="0"||!long.TryParse((string?)f.Attribute("pkt_pos"),out var position)||position<0||!int.TryParse((string?)f.Attribute("width"),out var w)||!int.TryParse((string?)f.Attribute("height"),out var h)||w is <=0 or >3840||h is <=0 or >2160)throw new NotSupportedException("Unsupported FEL enhancement sample profile.");return new EnhancementFrame(position,w,h);
        }).ToList();if(frames.Count is 0 or >HdrMetadataTimeline.MaximumFrames)throw new InvalidDataException("Invalid FEL enhancement inventory.");await process.FinishAsync(ct).ConfigureAwait(false);return frames;
    }
